            if (locationEl) locationEl.innerText = SafeGetValue(characterData, `${worldKey}.地点`, '未知地点');

            if (characterData.hasOwnProperty(characterKey)) {
                const rawAffection = SafeGetValue(characterData, `${characterKey}.好感度`, '0');
                updateProgressBar('linruoyu-affection-bar', 'linruoyu-affection', null, rawAffection, 0, 400, 'var(--accent-highlight)');

                const affectionValue = parseFloat(Array.isArray(rawAffection) && !isNaN(rawAffection[0]) ? rawAffection[0] : rawAffection);
                const stageNameEl = document.getElementById('linruoyu-stage-name');
                let stageName = "相敬如賓";
                if (affectionValue >= 300) {
                    stageName = "心意相通";
                } else if (affectionValue >= 200) {
                    stageName = "漸生情愫";
                } else if (affectionValue >= 100) {
                    stageName = "試探磨合";
                }
                if (stageNameEl) stageNameEl.innerText = stageName;
            }

        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}</p>`;
        }
    }

